fn intern_owner(
    census: &Arc<crate::nominal_boundary::census::Census>,
    owners: &mut Vec<Arc<crate::nominal_boundary::census::Census>>,
) -> Result<Arc<crate::nominal_boundary::census::Census>, String> {
    for owner in owners.iter() {
        if owner.context == census.context {
            if **owner == **census {
                return Ok(Arc::clone(owner));
            }
            if !same_inventory(owner, census)? {
                return Err("Contradictory source snapshots in one selected-unit context".into());
            }
            // Equivalent orderings keep separate owners to preserve readable order.
        }
    }
    owners.push(Arc::clone(census));
    Ok(Arc::clone(census))
}

fn same_inventory(
    first: &crate::nominal_boundary::census::Census,
    second: &crate::nominal_boundary::census::Census,
) -> Result<bool, String> {
    use crate::nominal_boundary::census::check_budget;
    check_budget(first)?;
    check_budget(second)?;

    let files = |census: &crate::nominal_boundary::census::Census| {
        census
            .files
            .iter()
            .map(|file| (file.path.clone(), file.clone()))
            .collect::<BTreeMap<_, _>>()
    };
    let a = files(first);
    let b = files(second);

    Ok(first.identity == second.identity
        && first.expansions == second.expansions
        && a.len() == first.files.len()
        && b.len() == second.files.len()
        && a == b)
}

pub fn check_budget(census: &Census) -> Result<(), String> {
    let bytes = census.files.iter().try_fold(0usize, |total, file| {
        total
            .checked_add(file.bytes.len())
            .ok_or("Source census byte overflow")
    })?;
    if census.external_imports.len() > MAX_FILES
        || census
            .external_imports
            .iter()
            .any(|import| import.exports.macros.len() > MAX_FILES)
        || census.documentation.len() > MAX_FILES
        || census.expansions.len() > MAX_FILES
        || census
            .expansions
            .iter()
            .any(|record| record.chain.len() > 128)
    {
        return Err("Module expansion inventory exceeds source census budget".into());
    }
    if census.files.len() > MAX_FILES || bytes > MAX_BYTES {
        return Err("Source census exceeds file/byte budget".into());
    }
    Ok(())
}

